static gboolean
dependency_idle_refresh(gpointer user_data)
{
    dependency_refresh(user_data);
    return G_SOURCE_REMOVE;
}

static gpointer
dependency_get_module_data(AppState *state)
{
    DependencyPage *manager = g_new0(DependencyPage, 1);
    manager->state = state;
    g_idle_add(dependency_idle_refresh, manager);
    return manager;
}

