    gtk_widget_add_css_class(running_lbl, "dependency-summary");
    gtk_widget_add_css_class(iface_lbl, "dependency-summary");
    gtk_widget_add_css_class(ssid_lbl, "dependency-summary");
    gtk_widget_add_css_class(chan_lbl, "dependency-summary");
    gtk_widget_add_css_class(creds_lbl, "dependency-summary");
