static gpointer
eviltwin_get_module_data(AppState *state)
{
    EvilTwinPage *manager = g_new0(EvilTwinPage, 1);
    manager->state = state;
    manager->adapter_ifaces = g_ptr_array_new_with_free_func(g_free);
    manager->destroyed = FALSE;
    manager->pending_ops = 0;

    g_idle_add(eviltwin_bootstrap_idle, manager);
    manager->poll_id = g_timeout_add_seconds(
        3, eviltwin_poll_cb, manager);

    return manager;
}

