static gpointer
bt_recon_get_module_data(AppState *state)
{
    BtReconPage *manager = g_new0(BtReconPage, 1);
    manager->state = state;
    manager->adapter_ifaces =
        g_ptr_array_new_with_free_func(g_free);
    manager->destroyed = FALSE;
    manager->pending_ops = 0;

    g_idle_add(bt_recon_bootstrap_idle, manager);
    manager->poll_id = g_timeout_add_seconds(
        5, bt_recon_poll_cb, manager);

    return manager;
}

