    gtk_box_append(GTK_BOX(card), current_lbl);
    gtk_box_append(GTK_BOX(card), loot_lbl);
    gtk_box_append(GTK_BOX(auto_card), auto_title);
    gtk_box_append(GTK_BOX(auto_card), autotune_btn);
