    gtk_label_set_xalign(GTK_LABEL(gps_dev_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(kismet_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(mon_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(dir_lbl), 0.0f);
    gtk_label_set_wrap(GTK_LABEL(subtitle), TRUE);
    gtk_widget_set_halign(refresh, GTK_ALIGN_START);

    manager->overview_gps = gps_lbl;
    manager->overview_gps_dev = gps_dev_lbl;
    manager->overview_kismet = kismet_lbl;
    manager->overview_mon = mon_lbl;
    manager->overview_dir = dir_lbl;

    gtk_box_append(GTK_BOX(card), card_title);
    gtk_box_append(GTK_BOX(card), gps_lbl);
    gtk_box_append(GTK_BOX(card), gps_dev_lbl);
    gtk_box_append(GTK_BOX(card), kismet_lbl);
    gtk_box_append(GTK_BOX(card), mon_lbl);
    gtk_box_append(GTK_BOX(card), dir_lbl);

    gtk_box_append(GTK_BOX(page), title);
    gtk_box_append(GTK_BOX(page), subtitle);
    gtk_box_append(GTK_BOX(page), card);
    gtk_box_append(GTK_BOX(page), refresh);

    g_signal_connect(refresh, "clicked",
        G_CALLBACK(wardrive_refresh_clicked), manager);

    g_object_set_data_full(G_OBJECT(page), "wardrive-manager",
                           manager, wardrive_page_free);

    {
        GtkWidget *pcard = gtk_box_new(GTK_ORIENTATION_VERTICAL, 8);
        GtkWidget *ptitle = gtk_label_new("PWN HUNTER");
        GtkWidget *prow = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
        GtkWidget *pnote = gtk_label_new(
            "bettercap recon plus handshake and PMKID collection. Export "
            "copies what was collected into the loot directory.");
        GtkWidget *scroll = fp_text_view();
        WdPwnCtx *pctx = g_new0(WdPwnCtx, 1);
        static const struct { const char *label; const char *verb; } pwn[] = {
            { "Check stack", "--check-stack"     },
            { "Start",       "--pwn-start"       },
            { "Stop",        "--pwn-stop"        },
            { "Status",      "--pwn-status-tsv"  },
            { "Export",      "--pwn-export"      },
        };

        gtk_widget_add_css_class(pcard, "section-card");
        gtk_widget_add_css_class(ptitle, "section-title");
        gtk_widget_add_css_class(pnote, "dependency-summary");
        gtk_label_set_xalign(GTK_LABEL(ptitle), 0.0f);
        gtk_label_set_xalign(GTK_LABEL(pnote), 0.0f);
        gtk_label_set_wrap(GTK_LABEL(pnote), TRUE);
        gtk_widget_set_halign(prow, GTK_ALIGN_START);
        gtk_widget_set_size_request(scroll, -1, 130);

        pctx->state = state;
        pctx->view = gtk_scrolled_window_get_child(
            GTK_SCROLLED_WINDOW(scroll));

        for (guint pi = 0; pi < G_N_ELEMENTS(pwn); pi++) {
            GtkWidget *b = gtk_button_new_with_label(pwn[pi].label);
            g_object_set_data(G_OBJECT(b), "wd-verb", (gpointer) pwn[pi].verb);
            g_signal_connect(b, "clicked", G_CALLBACK(wd_pwn_run), pctx);
            gtk_box_append(GTK_BOX(prow), b);
        }
        gtk_box_append(GTK_BOX(pcard), ptitle);
        gtk_box_append(GTK_BOX(pcard), prow);
        gtk_box_append(GTK_BOX(pcard), pnote);
        gtk_box_append(GTK_BOX(pcard), scroll);
        gtk_box_append(GTK_BOX(page), pcard);
    }
    return page;
