static GtkWidget *
arp_build_overview(AppState *state, gpointer module_data)
{
    ArpPage *manager = module_data;
    GtkWidget *page = gtk_box_new(GTK_ORIENTATION_VERTICAL, 12);
    GtkWidget *title = gtk_label_new("ARP / MITM");
    GtkWidget *subtitle = gtk_label_new(
        "ARP poisoning and man-in-the-middle traffic capture on a "
        "local subnet. Works over Ethernet or a managed Wi-Fi link.");
    GtkWidget *card = gtk_box_new(GTK_ORIENTATION_VERTICAL, 6);
    GtkWidget *card_title = gtk_label_new("STATUS");
    GtkWidget *iface_lbl = gtk_label_new("—");
    GtkWidget *gw_lbl = gtk_label_new("—");
    GtkWidget *local_lbl = gtk_label_new("—");
    GtkWidget *target_lbl = gtk_label_new("—");
    GtkWidget *refresh = gtk_button_new_with_label("Refresh");

    (void) state;

    gtk_widget_add_css_class(page, "dependency-page");
    gtk_widget_add_css_class(title, "page-title");
    gtk_widget_add_css_class(subtitle, "page-subtitle");
    gtk_widget_add_css_class(card, "section-card");
    gtk_widget_add_css_class(card_title, "section-title");
    gtk_widget_add_css_class(iface_lbl, "dependency-summary");
    gtk_widget_add_css_class(gw_lbl, "dependency-summary");
    gtk_widget_add_css_class(local_lbl, "dependency-summary");
    gtk_widget_add_css_class(target_lbl, "dependency-summary");

    gtk_label_set_xalign(GTK_LABEL(title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(subtitle), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(card_title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(iface_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(gw_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(local_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(target_lbl), 0.0f);
    gtk_label_set_wrap(GTK_LABEL(subtitle), TRUE);
    gtk_widget_set_halign(refresh, GTK_ALIGN_START);

    manager->overview_iface = iface_lbl;
    manager->overview_gateway = gw_lbl;
    manager->overview_local = local_lbl;
    manager->overview_target = target_lbl;

    gtk_box_append(GTK_BOX(card), card_title);
    gtk_box_append(GTK_BOX(card), iface_lbl);
    gtk_box_append(GTK_BOX(card), gw_lbl);
    gtk_box_append(GTK_BOX(card), local_lbl);
    gtk_box_append(GTK_BOX(card), target_lbl);

    gtk_box_append(GTK_BOX(page), title);
    gtk_box_append(GTK_BOX(page), subtitle);
    gtk_box_append(GTK_BOX(page), card);
    gtk_box_append(GTK_BOX(page), refresh);

    g_signal_connect(refresh, "clicked",
        G_CALLBACK(arp_refresh_clicked), manager);

    g_object_set_data_full(G_OBJECT(page), "arp-manager",
                           manager, arp_page_free);

    return page;
}

