static GtkWidget *
arp_build_scan(AppState *state, gpointer module_data)
{
    ArpPage *manager = module_data;
    GtkWidget *page = gtk_box_new(GTK_ORIENTATION_VERTICAL, 8);
    GtkWidget *top = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
    GtkWidget *title = gtk_label_new("Discover hosts on the local subnet");
    GtkWidget *scan = gtk_button_new_with_label("Run arp-scan");
    GtkWidget *status = gtk_label_new("");
    GtkWidget *scroll = gtk_scrolled_window_new();
    GtkWidget *list = gtk_list_box_new();

    (void) state;

    gtk_widget_add_css_class(page, "dependency-page");
    gtk_widget_add_css_class(title, "page-subtitle");
    gtk_widget_add_css_class(status, "dependency-summary");
    gtk_widget_add_css_class(scan, "accent");

    gtk_label_set_xalign(GTK_LABEL(title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(status), 0.0f);
    gtk_widget_set_hexpand(title, TRUE);
    gtk_widget_set_valign(scan, GTK_ALIGN_CENTER);
    gtk_widget_set_vexpand(scroll, TRUE);

    gtk_list_box_set_selection_mode(GTK_LIST_BOX(list), GTK_SELECTION_NONE);
    gtk_list_box_set_show_separators(GTK_LIST_BOX(list), TRUE);
    gtk_scrolled_window_set_policy(GTK_SCROLLED_WINDOW(scroll),
        GTK_POLICY_AUTOMATIC, GTK_POLICY_AUTOMATIC);
    gtk_scrolled_window_set_child(GTK_SCROLLED_WINDOW(scroll), list);

    gtk_box_append(GTK_BOX(top), title);
    gtk_box_append(GTK_BOX(top), scan);
    /* The stored host list, so a target can be chosen without waiting for a
       fresh sweep. --list-hosts-tsv had no caller at all. */
    {
        GtkWidget *known = gtk_button_new_with_label("List known hosts");
        const char *const a_known[] = { "pkexec", ARP_SCRIPT,
                                        "--list-hosts-tsv", NULL };
        g_object_set_data_full(G_OBJECT(known), "arp-argv",
            g_strdupv((gchar **) a_known), (GDestroyNotify) g_strfreev);
        g_signal_connect(known, "clicked", G_CALLBACK(arp_run_argv), manager);
        gtk_box_append(GTK_BOX(top), known);
    }
    gtk_box_append(GTK_BOX(page), top);
    gtk_box_append(GTK_BOX(page), status);
    gtk_box_append(GTK_BOX(page), scroll);

    manager->scan_button = scan;
    manager->scan_status = status;
    manager->hosts_list = list;

    g_signal_connect(scan, "clicked",
        G_CALLBACK(arp_scan_clicked), manager);

    return page;
}

