static gpointer
rogue_dhcp_get_module_data(AppState *state)
{
    RogueDhcpPage *manager = g_new0(RogueDhcpPage, 1);
    manager->state = state;
    manager->iface_names = g_ptr_array_new_with_free_func(g_free);
    g_idle_add(rogue_dhcp_idle_refresh, manager);
    return manager;
}

