    gtk_widget_add_css_class(sc_caps_btn, "accent");

    gtk_label_set_xalign(GTK_LABEL(title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(subtitle), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(card_title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(mon_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(target_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(chan_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(pcaps_lbl), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(loot_lbl), 0.0f);
