static void
hid_mj_scan_clicked(GtkButton *b, gpointer ud)
{
    HidPage *manager = ud;
    const char *argv[] = { HID_SCRIPT, "--mj-scan", NULL };
    (void) b;
    wf_action_run(manager->state, "12_hid_injection",
                  "Mousejack scan", manager->mj_status,
                  argv, FALSE);
}

static void
hid_mj_sniff_clicked(GtkButton *b, gpointer ud)
{
    HidPage *manager = ud;
    const char *argv[5];
    guint i = 0;
    (void) b;
    argv[i++] = HID_SCRIPT;
    argv[i++] = "--mj-sniff";
    if (manager->mj_target_entry != NULL) {
        const char *mac = gtk_editable_get_text(
            GTK_EDITABLE(manager->mj_target_entry));
        if (mac != NULL && *mac != '\0') argv[i++] = mac;
    }
    argv[i] = NULL;
    wf_action_run(manager->state, "12_hid_injection",
                  "Mousejack sniff", manager->mj_status,
                  argv, FALSE);
}

static void
hid_mj_replay_clicked(GtkButton *b, gpointer ud)
{
    HidPage *manager = ud;
    const char *mac = NULL;
    const char *payload = NULL;
    const char *argv[5];
    guint i = 0;
    (void) b;
    if (manager->mj_target_entry != NULL)
        mac = gtk_editable_get_text(
            GTK_EDITABLE(manager->mj_target_entry));
    if (manager->mj_payload_entry != NULL)
        payload = gtk_editable_get_text(
            GTK_EDITABLE(manager->mj_payload_entry));
    if (mac == NULL || *mac == '\0') {
        show_toast_module(manager->state, "12_hid_injection",
            "Target MAC required", "warn");
        return;
    }
    if (payload == NULL || *payload == '\0') {
        show_toast_module(manager->state, "12_hid_injection",
            "Payload path required", "warn");
        return;
    }
    argv[i++] = HID_SCRIPT;
    argv[i++] = "--mj-replay";
    argv[i++] = mac;
    argv[i++] = payload;
    argv[i] = NULL;
    wf_action_run(manager->state, "12_hid_injection",
                  "Mousejack replay", manager->mj_status,
                  argv, FALSE);
}

