    m->w3_teap_chk = teap;
    m->w3_tls_dd   = tls_dd;
    m->w3_mode_sw  = mode_sw;
    m->w3_pinning_sw = pin_sw;
    m->w3_teap_dg_sw = teap_sw;
    m->w3_peap_strip_sw = strip_sw;
    m->w3_status = status;

    gtk_box_append(GTK_BOX(mrow), peap);
    gtk_box_append(GTK_BOX(mrow), ttls);
    gtk_box_append(GTK_BOX(mrow), tls);
    gtk_box_append(GTK_BOX(mrow), teap);
    gtk_box_append(GTK_BOX(card), card_title);
    gtk_box_append(GTK_BOX(card), mrow);

    gtk_box_append(GTK_BOX(tls_row), tls_lbl);
