static GtkWidget *
bt_cve_build_results(AppState *state, gpointer module_data)
{
    BtCvePage *manager = module_data;
    GtkWidget *page = gtk_box_new(GTK_ORIENTATION_VERTICAL, 8);
    GtkWidget *row = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
    GtkWidget *label = gtk_label_new("CVE fingerprint results");
    GtkWidget *refresh = gtk_button_new_with_label("Reload");
    GtkWidget *scroll = gtk_scrolled_window_new();
    GtkWidget *view = gtk_text_view_new();

    (void) state;

    gtk_widget_add_css_class(page, "dependency-page");
    gtk_widget_add_css_class(label, "page-subtitle");
    gtk_widget_add_css_class(view, "event-view");

    gtk_label_set_xalign(GTK_LABEL(label), 0.0f);
    gtk_widget_set_hexpand(label, TRUE);
    gtk_widget_set_vexpand(scroll, TRUE);
    gtk_widget_set_valign(refresh, GTK_ALIGN_CENTER);

    gtk_text_view_set_editable(GTK_TEXT_VIEW(view), FALSE);
    gtk_text_view_set_cursor_visible(GTK_TEXT_VIEW(view), FALSE);
    gtk_text_view_set_monospace(GTK_TEXT_VIEW(view), TRUE);
    gtk_text_view_set_wrap_mode(GTK_TEXT_VIEW(view), GTK_WRAP_NONE);

    manager->results_buffer = gtk_text_view_get_buffer(GTK_TEXT_VIEW(view));

    gtk_scrolled_window_set_child(GTK_SCROLLED_WINDOW(scroll), view);
    gtk_scrolled_window_set_policy(GTK_SCROLLED_WINDOW(scroll),
        GTK_POLICY_AUTOMATIC, GTK_POLICY_AUTOMATIC);

    gtk_box_append(GTK_BOX(row), label);
    gtk_box_append(GTK_BOX(row), refresh);
    gtk_box_append(GTK_BOX(page), row);
    gtk_box_append(GTK_BOX(page), scroll);

    g_signal_connect(refresh, "clicked",
        G_CALLBACK(bt_cve_results_refresh_clicked), manager);

    bt_cve_results_reload(manager);

    return page;
}

