    gtk_widget_set_valign(url_lbl, GTK_ALIGN_CENTER);
    gtk_widget_set_valign(name_lbl, GTK_ALIGN_CENTER);
    gtk_widget_set_valign(dl_btn, GTK_ALIGN_CENTER);
    gtk_widget_set_valign(install_btn, GTK_ALIGN_CENTER);

    manager->dl_url_entry = url_entry;
    manager->dl_name_entry = name_entry;
    manager->dl_button = dl_btn;
    manager->dl_install_button = install_btn;
    manager->dl_status = status;

    gtk_box_append(GTK_BOX(url_row), url_lbl);
    gtk_box_append(GTK_BOX(url_row), url_entry);
    gtk_box_append(GTK_BOX(name_row), name_lbl);
    gtk_box_append(GTK_BOX(name_row), name_entry);
    gtk_box_append(GTK_BOX(btn_row), dl_btn);
    gtk_box_append(GTK_BOX(btn_row), install_btn);

    gtk_box_append(GTK_BOX(card), card_title);
    gtk_box_append(GTK_BOX(card), url_row);
    gtk_box_append(GTK_BOX(card), name_row);
    gtk_box_append(GTK_BOX(card), btn_row);
    gtk_box_append(GTK_BOX(card), status);

    gtk_box_append(GTK_BOX(presets_row), p1);
    gtk_box_append(GTK_BOX(presets_row), p2);

    /* SecLists had four verbs and no buttons: the collection could only be
       cloned, listed, checked or updated from a shell. */
