        for (guint i = 0; i < G_N_ELEMENTS(sl); i++) {
            GtkWidget *b = gtk_button_new_with_label(sl[i].label);
            g_object_set_data(G_OBJECT(b), "sl-verb", (gpointer) sl[i].verb);
            g_signal_connect(b, "clicked",
                G_CALLBACK(wordlist_sl_run), manager);
            gtk_box_append(GTK_BOX(sl_row), b);
        }

        manager->sl_view = gtk_scrolled_window_get_child(
            GTK_SCROLLED_WINDOW(sl_view_scroll));
