static void
karma_wl_add_clicked(GtkButton *button, gpointer user_data)
{
    KarmaPage *manager = user_data;
    const char *prefix = NULL;
    const char *argv[4];
    guint i = 0;
    (void) button;

    if (manager->wl_entry != NULL)
        prefix = gtk_editable_get_text(GTK_EDITABLE(manager->wl_entry));

    if (prefix == NULL || *prefix == '\0') {
        if (manager->wl_status != NULL)
            gtk_label_set_text(GTK_LABEL(manager->wl_status),
                "SSID prefix required");
        return;
    }

    argv[i++] = KARMA_SCRIPT;
    argv[i++] = "--whitelist-add";
    argv[i++] = prefix;
    argv[i] = NULL;

    /* Whitelist lives under tmp/, which the user owns. */
    wf_action_run(manager->state, "20_karma",
                  "Karma whitelist add", manager->wl_status,
                  argv, FALSE);
}

