        GtkWidget *t = gtk_label_new("CONTROLS");
        gtk_widget_add_css_class(card, "section-card");
        gtk_widget_add_css_class(t, "section-title");
        gtk_label_set_xalign(GTK_LABEL(t), 0.0f);
        gtk_box_append(GTK_BOX(card), t);

        GtkWidget *row = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
        m->watch_start_btn = gtk_button_new_with_label("Start watching");
        m->watch_stop_btn  = gtk_button_new_with_label("Stop");
        GtkWidget *clear   = gtk_button_new_with_label("Clear hits");
        m->watch_notify_toggle =
            gtk_check_button_new_with_label("Notify on hit");
        m->watch_status = gtk_label_new("idle");

        gtk_widget_add_css_class(m->watch_start_btn, "accent");
        gtk_widget_add_css_class(m->watch_status, "dependency-summary");
        gtk_check_button_set_active(
            GTK_CHECK_BUTTON(m->watch_notify_toggle), TRUE);
