static void
p2p_capture_start_clicked(GtkButton *button, gpointer user_data)
{
    P2pPage *manager = user_data;
    g_autoptr(GError) error = NULL;
    const char *argv[] = { "pkexec", P2P_SCRIPT, "--capture-start", NULL };
    GSubprocess *proc;
    (void) button;

    proc = g_subprocess_newv(argv, G_SUBPROCESS_FLAGS_NONE, &error);
    if (proc == NULL) return;
    g_object_unref(proc);
    gtk_label_set_text(GTK_LABEL(manager->capture_status), "Starting…");
    append_event(manager->state, "P2P continuous capture started");
    g_timeout_add_seconds(3, G_SOURCE_FUNC(p2p_refresh), manager);
    module_page_set_status(manager->state, "22_wifi_direct", "Capturing", "status-running");
}

