static void
p2p_analyze_clicked(GtkButton *button, gpointer user_data)
{
    P2pPage *manager = user_data;
    const char *path = NULL;
    const char *argv[4];
    guint i = 0;
    (void) button;

    if (manager->analyze_entry != NULL)
        path = gtk_editable_get_text(GTK_EDITABLE(manager->analyze_entry));

    argv[i++] = P2P_SCRIPT;
    argv[i++] = "--analyze";
    if (path != NULL && *path != '\0')
        argv[i++] = path;
    argv[i] = NULL;

    /* Offline tshark pass; the report lands in user-owned loot. */
    wf_action_run(manager->state, "22_wifi_direct",
                  "Analyze P2P pcap", manager->analyze_status,
                  argv, FALSE);
}

static void
p2p_gon_clicked(GtkButton *button, gpointer user_data)
{
    P2pPage *manager = user_data;
    const char *iface = NULL;
    const char *target = NULL;
    const char *ssid = NULL;
    const char *argv[6];
    guint i = 0;
    (void) button;

    if (manager->gon_iface_entry != NULL)
        iface = gtk_editable_get_text(
            GTK_EDITABLE(manager->gon_iface_entry));
    if (manager->gon_target_entry != NULL)
        target = gtk_editable_get_text(
            GTK_EDITABLE(manager->gon_target_entry));
    if (manager->gon_ssid_entry != NULL)
        ssid = gtk_editable_get_text(
            GTK_EDITABLE(manager->gon_ssid_entry));

    if (iface == NULL || *iface == '\0' ||
        target == NULL || *target == '\0') {
        if (manager->gon_status != NULL)
            gtk_label_set_text(GTK_LABEL(manager->gon_status),
                "Interface and target MAC are required");
        return;
    }

    argv[i++] = P2P_SCRIPT;
    argv[i++] = "--spoof-go-neg";
    argv[i++] = iface;
    argv[i++] = target;
    if (ssid != NULL && *ssid != '\0')
        argv[i++] = ssid;
    argv[i] = NULL;

    /* Scapy frame injection needs raw socket access. */
    wf_action_run(manager->state, "22_wifi_direct",
                  "Spoof GO Negotiation", manager->gon_status,
                  argv, TRUE);
}

