static gpointer
p2p_get_module_data(AppState *state)
{
    P2pPage *manager = g_new0(P2pPage, 1);
    manager->state = state;
    manager->destroyed = FALSE;
    manager->pending_ops = 0;

    g_idle_add(p2p_idle_refresh, manager);
    manager->poll_id = g_timeout_add_seconds(
        5, p2p_poll_cb, manager);

    return manager;
}

