        gtk_widget_add_css_class(plot_label, "section-title");
        gtk_widget_add_css_class(plot_area, "spectrum-plot");
        gtk_label_set_xalign(GTK_LABEL(plot_label), 0.0f);
        gtk_widget_set_size_request(plot_area, -1, 220);
        gtk_drawing_area_set_draw_func(
            GTK_DRAWING_AREA(plot_area), spectrum_plot_draw, manager, NULL);
