static gpointer
zigbee_get_module_data(AppState *state)
{
    ZigbeePage *manager = g_new0(ZigbeePage, 1);
    manager->state = state;
    manager->destroyed = FALSE;
    manager->pending_ops = 0;

    g_idle_add(zigbee_idle_refresh, manager);
    manager->poll_id = g_timeout_add_seconds(
        5, zigbee_poll_cb, manager);

    return manager;
}

