{
    SbPage *p = module_data;
    const SbModule *d = p->def;
    GtkWidget *page = gtk_box_new(GTK_ORIENTATION_VERTICAL, 12);
    GtkWidget *title = gtk_label_new(d->title);
    GtkWidget *subtitle = gtk_label_new(d->subtitle);
    GtkWidget *caps_title = gtk_label_new("STATE");
    GtkWidget *caps_card = gtk_box_new(GTK_ORIENTATION_VERTICAL, 4);
    GtkWidget *caps = gtk_label_new("Probing capabilities...");
    GtkWidget *ref_title = gtk_label_new("REFERENCE");
    GtkWidget *ref_card = gtk_box_new(GTK_ORIENTATION_VERTICAL, 4);
    GtkWidget *scroll = gtk_scrolled_window_new();
    GtkWidget *view = gtk_text_view_new();
    GtkWidget *refresh = gtk_button_new_with_label("Refresh state");
    GtkTextBuffer *buf = sb_out_buffer(p);

    (void) state;

    gtk_widget_add_css_class(page, "dependency-page");
    gtk_widget_add_css_class(title, "page-title");
    gtk_widget_add_css_class(subtitle, "page-subtitle");
    gtk_widget_add_css_class(caps_card, "section-card");
    gtk_widget_add_css_class(caps_title, "section-title");
    gtk_widget_add_css_class(ref_card, "section-card");
    gtk_widget_add_css_class(ref_title, "section-title");
    gtk_widget_add_css_class(caps, "dependency-summary");
    gtk_widget_add_css_class(view, "event-view");
    gtk_widget_add_css_class(refresh, "accent");
    gtk_label_set_xalign(GTK_LABEL(title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(subtitle), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(caps_title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(ref_title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(caps), 0.0f);
    gtk_label_set_wrap(GTK_LABEL(subtitle), TRUE);
    gtk_label_set_wrap(GTK_LABEL(caps), TRUE);

    gtk_text_view_set_buffer(GTK_TEXT_VIEW(view), buf);
    gtk_text_view_set_editable(GTK_TEXT_VIEW(view), FALSE);
    gtk_text_view_set_monospace(GTK_TEXT_VIEW(view), TRUE);
    gtk_widget_set_size_request(view, -1, 260);
    gtk_widget_set_vexpand(scroll, TRUE);
    gtk_scrolled_window_set_child(GTK_SCROLLED_WINDOW(scroll), view);

    gtk_box_append(GTK_BOX(caps_card), caps_title);
    gtk_box_append(GTK_BOX(caps_card), caps);
    gtk_box_append(GTK_BOX(ref_card), ref_title);
    gtk_box_append(GTK_BOX(ref_card), scroll);

    gtk_box_append(GTK_BOX(page), title);
    gtk_box_append(GTK_BOX(page), subtitle);
    gtk_box_append(GTK_BOX(page), caps_card);
    gtk_box_append(GTK_BOX(page), refresh);
    gtk_box_append(GTK_BOX(page), ref_card);

    p->caps = caps;
    p->status = NULL;   /* the group pages own the status line */
    g_object_set_data(G_OBJECT(refresh), "sb-page", p);
    g_object_set_data(G_OBJECT(refresh), "sb-verb", (gpointer) "--info");
    g_signal_connect(refresh, "clicked", G_CALLBACK(sb_action_clicked), p);

    sb_refresh_caps(p);
    /* Load the reference prose immediately so Overview is never empty. */
    sb_run(p, "--info", NULL);

    g_object_set_data_full(G_OBJECT(page), "sb-page", p, NULL);
    return page;
}

/* Shows only the actions belonging to group `idx`. */
static GtkWidget *
sb_build_group(AppState *state, gpointer module_data, int idx)
{
    SbPage *p = module_data;
    const SbModule *d = p->def;
    const char *groups[16];
    int ngroups = sb_groups(d, groups, 16);
    const char *want = (idx < ngroups) ? groups[idx] : NULL;
    GtkWidget *page = gtk_box_new(GTK_ORIENTATION_VERTICAL, 12);
    GtkWidget *title;
    GtkWidget *card;
    GtkWidget *status = gtk_label_new("idle");
    GtkWidget *scroll = gtk_scrolled_window_new();
    GtkWidget *view = gtk_text_view_new();
    GtkTextBuffer *buf = sb_out_buffer(p);

    (void) state;

    if (want == NULL) {
        GtkWidget *none = gtk_label_new("No actions in this group.");
        return none;
    }

    title = gtk_label_new(want);
    card = gtk_box_new(GTK_ORIENTATION_VERTICAL, 8);
    gtk_widget_add_css_class(page, "dependency-page");
    gtk_widget_add_css_class(title, "page-title");
    gtk_widget_add_css_class(card, "section-card");
    gtk_widget_add_css_class(status, "dependency-summary");
    gtk_widget_add_css_class(view, "event-view");
    gtk_label_set_xalign(GTK_LABEL(title), 0.0f);
    gtk_label_set_xalign(GTK_LABEL(status), 0.0f);
    gtk_label_set_wrap(GTK_LABEL(status), TRUE);

    for (int i = 0; i < d->n_actions; i++) {
        const SbAction *a = &d->actions[i];
        GtkWidget *row;
        GtkWidget *btn;

        if (g_strcmp0(a->group, want) != 0) continue;

        row = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
        btn = gtk_button_new_with_label(a->label);
        gtk_widget_add_css_class(btn, "accent");
        gtk_widget_set_valign(btn, GTK_ALIGN_CENTER);
        g_object_set_data(G_OBJECT(btn), "sb-page", p);
        g_object_set_data(G_OBJECT(btn), "sb-verb", (gpointer) a->verb);

        if (a->arg != NULL) {
            GtkWidget *entry = gtk_entry_new();
            gtk_entry_set_placeholder_text(GTK_ENTRY(entry), a->arg);
            gtk_widget_set_hexpand(entry, TRUE);
            gtk_box_append(GTK_BOX(row), entry);
            g_object_set_data(G_OBJECT(btn), "sb-entry", entry);
        } else if (a->privileged) {
            GtkWidget *hint = gtk_label_new("needs root");
            gtk_widget_add_css_class(hint, "dependency-package");
            gtk_widget_set_hexpand(hint, TRUE);
            gtk_label_set_xalign(GTK_LABEL(hint), 1.0f);
            gtk_box_append(GTK_BOX(row), hint);
        } else {
            GtkWidget *spacer = gtk_label_new("");
            gtk_widget_set_hexpand(spacer, TRUE);
            gtk_box_append(GTK_BOX(row), spacer);
        }
        gtk_box_append(GTK_BOX(row), btn);
        gtk_box_append(GTK_BOX(card), row);
        g_signal_connect(btn, "clicked", G_CALLBACK(sb_action_clicked), p);
    }

    gtk_text_view_set_buffer(GTK_TEXT_VIEW(view), buf);
    gtk_text_view_set_editable(GTK_TEXT_VIEW(view), FALSE);
    gtk_text_view_set_monospace(GTK_TEXT_VIEW(view), TRUE);
    gtk_widget_set_size_request(view, -1, 220);
    gtk_widget_set_vexpand(scroll, TRUE);
    gtk_scrolled_window_set_child(GTK_SCROLLED_WINDOW(scroll), view);

    gtk_box_append(GTK_BOX(page), title);
    gtk_box_append(GTK_BOX(page), card);
    gtk_box_append(GTK_BOX(page), status);
    gtk_box_append(GTK_BOX(page), scroll);

    p->status = status;
    g_object_set_data_full(G_OBJECT(page), "sb-page", p, NULL);
    return page;
}



