/* ── module data + submenu tables ───────────────────────────────────── */

static gpointer
sb_make_data(AppState *state, const SbModule *def)
{
    SbPage *p = g_new0(SbPage, 1);
    p->def = def;
    p->state = state;
    return p;
}

static gpointer pmf_get_module_data(AppState *s)   { return sb_make_data(s, &pmf_def); }
static gpointer w6_get_module_data(AppState *s)    { return sb_make_data(s, &w6_def); }
