/* ---- firmware pipeline stages ---- */

static void
firmware_stage_run(FirmwarePage *manager, const char *flag,
                   const char *label, gboolean with_pattern)
{
    const char *path;
    const char *pattern = NULL;

    path = gtk_editable_get_text(GTK_EDITABLE(manager->strings_path_entry));
    if (path == NULL || *path == '\0') {
        gtk_label_set_text(GTK_LABEL(manager->analysis_status),
            "Firmware image or directory required");
        return;
    }

    if (with_pattern && manager->strings_pattern_entry != NULL) {
        pattern = gtk_editable_get_text(
            GTK_EDITABLE(manager->strings_pattern_entry));
        if (pattern != NULL && *pattern == '\0') pattern = NULL;
    }

    if (pattern != NULL) {
        const char *full[] = {
            FIRMWARE_SCRIPT, flag, path, pattern, NULL
        };
        firmware_run_simple(manager, label, full);
    } else {
        const char *full[] = { FIRMWARE_SCRIPT, flag, path, NULL };
        firmware_run_simple(manager, label, full);
    }
}

