        gtk_box_append(GTK_BOX(card), row);
        gtk_box_append(GTK_BOX(page), card);
        g_signal_connect(dispatch, "clicked",
                         G_CALLBACK(rn_atk_dispatch_clicked), m);
        g_signal_connect(stop, "clicked",
                         G_CALLBACK(rn_atk_stop_clicked), m);
