        GtkWidget *l1 = gtk_label_new("Crack node:");
        GtkWidget *l2 = gtk_label_new("Hashfile:");
        gtk_widget_set_halign(l1, GTK_ALIGN_END);
        gtk_widget_set_halign(l2, GTK_ALIGN_END);
        gtk_widget_set_valign(l1, GTK_ALIGN_CENTER);
        gtk_widget_set_valign(l2, GTK_ALIGN_CENTER);
        gtk_grid_attach(GTK_GRID(grid), l1, 0, 0, 1, 1);
        gtk_grid_attach(GTK_GRID(grid), m->cg_node_dd, 1, 0, 1, 1);
        gtk_grid_attach(GTK_GRID(grid), l2, 0, 1, 1, 1);
        gtk_grid_attach(GTK_GRID(grid), m->cg_hash_entry, 1, 1, 1, 1);
        gtk_box_append(GTK_BOX(card), grid);
        GtkWidget *row = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
        GtkWidget *submit = gtk_button_new_with_label("Submit");
        GtkWidget *refresh = gtk_button_new_with_label("Refresh queue");
        m->cg_status = gtk_label_new("");
        gtk_widget_add_css_class(submit, "accent");
        gtk_widget_add_css_class(m->cg_status, "dependency-summary");
