/* ---------- helpers ---------- */

static gchar *
rp_run_sync(const char *const *argv)
{
    g_autoptr(GError) error = NULL;
    GSubprocess *p = g_subprocess_newv(argv,
        G_SUBPROCESS_FLAGS_STDOUT_PIPE | G_SUBPROCESS_FLAGS_STDERR_SILENCE,
        &error);
    gchar *out = NULL, *errout = NULL;
    if (p == NULL) return NULL;
    if (!g_subprocess_communicate_utf8(p, NULL, NULL, &out, &errout, &error)) {
        g_object_unref(p);
        g_free(out); g_free(errout);
        return NULL;
    }
    g_object_unref(p);
    g_free(errout);
    return out;
}

