        GtkWidget *scroll = rp_text_view_new(NULL);
        m->start_log_view = gtk_scrolled_window_get_child(
            GTK_SCROLLED_WINDOW(scroll));
        gtk_widget_set_size_request(scroll, -1, 260);
        gtk_box_append(GTK_BOX(card), scroll);
