static void
rp_page_free(gpointer data)
{
    ResolverPoisonPage *m = data;
    if (m == NULL) return;
    m->destroyed = TRUE;
    if (m->poll_id != 0) {
        g_source_remove(m->poll_id);
        m->poll_id = 0;
    }
    g_free(m);
}

static gpointer
rp_get_module_data(AppState *state)
{
    ResolverPoisonPage *m = g_new0(ResolverPoisonPage, 1);
    m->state = state;
    m->destroyed = FALSE;
    m->poll_id = g_timeout_add_seconds(3, rp_overview_tick, m);
    return m;
}

