/* ==================================================================== */
/*  VHS / OLD TV STATIC BACKGROUND                                      */
/* ==================================================================== */

#define VHS_TILE   128
#define VHS_NTILES 4

typedef struct {
    GtkWidget       *area;
    guint            timer;
    cairo_surface_t *tiles[VHS_NTILES];
    int              idx;
    int              frame;
    int              drop_y;
    int              drop_h;
    int              drop_ttl;
    double           grid_offset;   /* drifting graph paper, same surface */
} AmbientVhs;

static cairo_surface_t *
vhs_new_tile(void)
{
    cairo_surface_t *s = cairo_image_surface_create(
        CAIRO_FORMAT_ARGB32, VHS_TILE, VHS_TILE);
    unsigned char *data = cairo_image_surface_get_data(s);
    int stride = cairo_image_surface_get_stride(s);
    int x, y;

    for (y = 0; y < VHS_TILE; y++) {
        guint32 *row = (guint32 *)(data + y * stride);
        for (x = 0; x < VHS_TILE; x++) {
            guint g  = g_random_int_range(30, 210);
            guint r  = g;
            guint gg = (g * 21) / 25;
            guint b  = (g * 19) / 25;
            row[x] = (0xFFu << 24) | (r << 16) | (gg << 8) | b;
        }
    }
    cairo_surface_mark_dirty(s);
    return s;
}

static void
vhs_draw(GtkDrawingArea *area, cairo_t *cr,
         int width, int height, gpointer user_data)
{
    AmbientVhs *v = user_data;
    int ox, oy;
    int y;

    (void) area;

    /* The surface is NOT cleared for us between frames, so this is required.
       CAIRO_OPERATOR_CLEAR writes transparent pixels with no blending, which
       measured ~11 points of a core cheaper than the default SOURCE_OVER
       paint of a transparent colour, for the identical result. */
    cairo_set_operator(cr, CAIRO_OPERATOR_CLEAR);
    cairo_paint(cr);
    cairo_set_operator(cr, CAIRO_OPERATOR_OVER);

    ox = g_random_int_range(0, VHS_TILE);
    oy = g_random_int_range(0, VHS_TILE);

    cairo_save(cr);
    cairo_set_source_surface(cr, v->tiles[v->idx], -ox, -oy);
    cairo_pattern_set_extend(cairo_get_source(cr), CAIRO_EXTEND_REPEAT);
    cairo_paint_with_alpha(cr, 0.055);
    cairo_restore(cr);

    cairo_set_source_rgba(cr, 0, 0, 0, 0.022);
    for (y = 0; y < height; y += 3)
        cairo_rectangle(cr, 0, y, width, 1);
    cairo_fill(cr);

    if (v->drop_ttl > 0) {
        cairo_set_source_rgba(cr, 1.0, 0.95, 0.90, 0.030);
        cairo_rectangle(cr, 0, v->drop_y, width, v->drop_h);
        cairo_fill(cr);
        cairo_set_source_rgba(cr, 1.0, 1.0, 1.0, 0.05);
        cairo_rectangle(cr, 0, v->drop_y, width, 1);
        cairo_fill(cr);
    }

    /* Graph paper, painted last so it sits above the static exactly as it did
       when it was a separate overlay child. */
    ambient_grid_paint(cr, width, height, v->grid_offset);
}

static gboolean
vhs_tick(gpointer user_data)
{
    AmbientVhs *v = user_data;

    if (v->area == NULL) return G_SOURCE_REMOVE;

    /* Minimised or otherwise off screen: skip the whole repaint. This is the
       single largest saving, because the backdrop covers the entire window. */
    if (!gtk_widget_get_mapped(v->area)) return G_SOURCE_CONTINUE;

    v->grid_offset -= 0.18;
    v->frame++;
    if ((v->frame % 3) == 0)
        v->idx = (v->idx + 1) % VHS_NTILES;

    if (v->drop_ttl > 0) {
        v->drop_ttl--;
    } else if (g_random_int_range(0, 100) < 2) {
        v->drop_y   = g_random_int_range(0, 800);
        v->drop_h   = g_random_int_range(3, 12);
        v->drop_ttl = g_random_int_range(2, 6);
    }

    gtk_widget_queue_draw(v->area);
    return G_SOURCE_CONTINUE;
}

static void
vhs_free(gpointer data)
{
    AmbientVhs *v = data;
    int i;
    if (v->timer) g_source_remove(v->timer);
    for (i = 0; i < VHS_NTILES; i++)
        if (v->tiles[i]) cairo_surface_destroy(v->tiles[i]);
    g_free(v);
}

static GtkWidget *
ambient_vhs_static_new(void)
{
    AmbientVhs *v = g_new0(AmbientVhs, 1);
    int i;

    for (i = 0; i < VHS_NTILES; i++)
        v->tiles[i] = vhs_new_tile();
    v->idx = 0;
    v->frame = 0;
    v->drop_ttl = 0;

    v->area = gtk_drawing_area_new();
    gtk_widget_set_can_target(v->area, FALSE);
    gtk_widget_set_hexpand(v->area, TRUE);
    gtk_widget_set_vexpand(v->area, TRUE);
    gtk_drawing_area_set_draw_func(
        GTK_DRAWING_AREA(v->area), vhs_draw, v, NULL);

    g_object_set_data_full(G_OBJECT(v->area), "ambient-vhs",
                           v, vhs_free);

    v->timer = g_timeout_add(50, vhs_tick, v);
    return v->area;
}




