static GtkWidget *
settings_toggle_row(SettingsPage *m, const char *title, const char *help,
                    GtkWidget **out_switch)
{
    GtkWidget *row = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
    GtkWidget *col = gtk_box_new(GTK_ORIENTATION_VERTICAL, 2);
    GtkWidget *l1 = gtk_label_new(title);
    GtkWidget *l2 = help != NULL ? gtk_label_new(help) : NULL;
    /* Toggle button, matching the rest of the app (button:checked is already
       styled in style.css); a GtkSwitch here looked foreign. */
    GtkWidget *sw = gtk_toggle_button_new_with_label("Enabled");

    gtk_widget_add_css_class(l1, "dependency-name");
    if (l2 != NULL) gtk_widget_add_css_class(l2, "dependency-package");
    gtk_label_set_xalign(GTK_LABEL(l1), 0.0f);
    if (l2 != NULL) {
        gtk_label_set_xalign(GTK_LABEL(l2), 0.0f);
        gtk_label_set_wrap(GTK_LABEL(l2), TRUE);
        gtk_box_append(GTK_BOX(col), l1);
        gtk_box_append(GTK_BOX(col), l2);
    } else {
        gtk_box_append(GTK_BOX(col), l1);
    }
    gtk_widget_set_hexpand(col, TRUE);
    gtk_widget_set_valign(sw, GTK_ALIGN_CENTER);

    gtk_box_append(GTK_BOX(row), col);
    gtk_box_append(GTK_BOX(row), sw);

    if (out_switch != NULL) *out_switch = sw;
    (void) m;
    return row;
}

static GtkWidget *
settings_entry_row(const char *title, const char *placeholder,
                   GtkWidget **out_entry)
{
    GtkWidget *row = gtk_box_new(GTK_ORIENTATION_HORIZONTAL, 8);
    GtkWidget *lbl = gtk_label_new(title);
    GtkWidget *entry = gtk_entry_new();

    gtk_label_set_xalign(GTK_LABEL(lbl), 0.0f);
    gtk_widget_set_valign(lbl, GTK_ALIGN_CENTER);
    gtk_widget_set_hexpand(entry, TRUE);
    gtk_widget_set_size_request(lbl, 190, -1);
    if (placeholder != NULL)
        gtk_entry_set_placeholder_text(GTK_ENTRY(entry), placeholder);

    gtk_box_append(GTK_BOX(row), lbl);
    gtk_box_append(GTK_BOX(row), entry);
    if (out_entry != NULL) *out_entry = entry;
    return row;
}

