/* Renders every module with the verbs it exposes, grouped by category.
   Built from the generated index, so a new module appears in Help without
   anyone remembering to edit a help string. */
static char *
help_build_module_index(void)
{
    GString *s = g_string_new(NULL);
    const char *last_cat = NULL;

    g_string_append(s,
        "Every module with the verbs it exposes, generated from the modules "
        "themselves by tools/gen-module-index.sh.\n\n"
        "Modules marked [self-tested] ship a --selftest you can run with "
        "tools/run-selftests.sh.\n");

    for (int i = 0; i < MODULE_INDEX_N; i++) {
        const ModuleIndexEntry *e = &module_index[i];
        if (g_strcmp0(last_cat, e->category) != 0) {
            g_string_append_printf(s, "\n\xe2\x94\x80\xe2\x94\x80 %s "
                                      "\xe2\x94\x80\xe2\x94\x80\n",
                                   e->category);
            last_cat = e->category;
        }
        g_string_append_printf(s, "\n%s  (%s)%s\n",
            e->name, e->id, e->has_selftest ? "  [self-tested]" : "");
        g_string_append_printf(s, "    %s\n",
            (e->verbs != NULL && *e->verbs != '\0') ? e->verbs
                                                     : "(no usage text)");
    }
    return g_string_free(s, FALSE);
}

static void
help_apply_text(GtkWidget *label, const char *text)
{
    gtk_label_set_text(GTK_LABEL(label), text);
    gtk_label_set_xalign(GTK_LABEL(label), 0.0f);
    gtk_label_set_wrap(GTK_LABEL(label), TRUE);
    gtk_label_set_selectable(GTK_LABEL(label), TRUE);
    gtk_label_set_wrap_mode(GTK_LABEL(label), PANGO_WRAP_WORD_CHAR);
}

static void
help_submenu_row_activated(GtkListBox *list,
                           GtkListBoxRow *row,
                           gpointer user_data)
{
    GtkStack *stack = user_data;
    int idx = gtk_list_box_row_get_index(row);
    if (idx < 0 || idx >= (int) G_N_ELEMENTS(help_sections)) return;

    gtk_stack_set_visible_child_name(
        stack, help_sections[idx].name);
    gtk_list_box_select_row(list, row);
}

