static void
action_goto_tab(GSimpleAction *action, GVariant *param, gpointer user_data)
{
    AppState *state = user_data;
    int n, pages;
    (void)action;
    if (param == NULL) return;
    n = g_variant_get_int32(param);
    pages = gtk_notebook_get_n_pages(GTK_NOTEBOOK(state->notebook));
    if (n < 1 || n > pages) return;
    gtk_notebook_set_current_page(GTK_NOTEBOOK(state->notebook), n - 1);
}

static void
action_close_tab(GSimpleAction *action, GVariant *param, gpointer user_data)
{
    AppState *state = user_data;
    int idx;
    (void)action; (void)param;
    idx = gtk_notebook_get_current_page(GTK_NOTEBOOK(state->notebook));
    if (idx <= 0) return;
    gtk_notebook_remove_page(GTK_NOTEBOOK(state->notebook), idx);
}

