static void
install_keyboard_shortcuts(AppState *state)
{
    GtkShortcutController *ctrl;
    GtkShortcutTrigger *trig;
    GtkShortcutAction *act;
    GtkShortcut *sh;

    static const GActionEntry win_actions[] = {
        { .name = "goto-tab",   .activate = action_goto_tab,   .parameter_type = "i" },
        { .name = "close-tab",  .activate = action_close_tab },
        { .name = "new-term",   .activate = action_new_term },
        { .name = "quit",       .activate = action_quit },
        { .name = "clear-evts", .activate = action_clear_events },
        { .name = "settings",   .activate = action_open_settings },
        { .name = "palette",    .activate = palette_show },
    };

    static const struct {
        const char *accel;
        const char *action;
    } simple[] = {
        { "<Control>t", "win.new-term" },
        { "<Control>w", "win.close-tab" },
        { "<Control>q", "win.quit" },
        { "<Control>k", "win.clear-evts" },
        { "<Control>comma", "win.settings" },
        { "<Control>p", "win.palette" },
        { NULL, NULL }
    };

    g_action_map_add_action_entries(
        G_ACTION_MAP(state->window), win_actions,
        G_N_ELEMENTS(win_actions), state);

    ctrl = GTK_SHORTCUT_CONTROLLER(gtk_shortcut_controller_new());
    gtk_shortcut_controller_set_scope(ctrl, GTK_SHORTCUT_SCOPE_GLOBAL);

    for (int i = 0; simple[i].accel != NULL; i++) {
        trig = gtk_shortcut_trigger_parse_string(simple[i].accel);
        act = gtk_named_action_new(simple[i].action);
        sh = gtk_shortcut_new(trig, act);
        gtk_shortcut_controller_add_shortcut(ctrl, sh);
    }

    for (int n = 1; n <= 9; n++) {
        char accel[32];
        g_snprintf(accel, sizeof accel, "<Control>%d", n);
        trig = gtk_shortcut_trigger_parse_string(accel);
        act = gtk_named_action_new("win.goto-tab");
        sh = gtk_shortcut_new(trig, act);
        g_object_set(sh, "arguments", g_variant_new_int32(n), NULL);
        gtk_shortcut_controller_add_shortcut(ctrl, sh);
    }

    gtk_widget_add_controller(
        GTK_WIDGET(state->window), GTK_EVENT_CONTROLLER(ctrl));
}

